{
  "items": [
    {
      "title": "ARD/ZDF Online Study (2010–2019)",
      "url_or_doi": "https://www.ard-zdf-onlinestudie.de/",
      "justification": "An annual German media research study examining internet usage, digital media consumption, online video, social media, and changing media habits. Provides historical data covering the entire 2010s, including demographic breakdowns by age and other characteristics. Particularly useful for analyzing the digital transformation of Germany's media landscape."
    },
    {
      "title": "ARD/ZDF Media Study – German Media Consumption",
      "url_or_doi": "https://b2find.eudat.eu/dataset/bd28b4b7-1e41-5dfd-90c8-537107b5bbde",
      "justification": "A research dataset documenting media consumption patterns in Germany, incorporating the long-running ARD/ZDF mass communication studies and online media research. Includes information relevant to television, radio, internet, and other media formats. Useful for studying long-term changes in German media consumption, including during the 2010s."
    },
    {
      "title": "Reuters Institute Digital News Report – Germany (2013–2019)",
      "url_or_doi": "https://newws.leibniz-hbi.de/en/hbi-projects/reuters-institute-digital-news-report/",
      "justification": "Annual survey research examining news consumption in Germany, including digital news platforms, traditional media, social networks, news trust, and audience behavior. The Leibniz Institute for Media Research provides Germany-specific findings for multiple years throughout the 2010s. Particularly relevant for studying journalism, digital news consumption, and the evolution of German news audiences."
    },
    {
      "title": "Reuters Institute Digital News Report 2015 – Interactive Dataset",
      "url_or_doi": "https://reutersinstitute.politics.ox.ac.uk/digital-news-report/archive/survey/2015/index.html",
      "justification": "Interactive survey dataset covering online news consumption in Germany and other countries in 2015. Includes information on news sources, digital devices, audience behavior, and online news engagement. Allows researchers to explore and compare Germany's digital news consumption patterns with those of other countries."
    },
    {
      "title": "Reuters Digital News Report 2019 – Interactive Dataset",
      "url_or_doi": "https://www.rcmediafreedom.eu/Media-freedom-datasets/Reuters-Digital-News-Report-2019-Interactive",
      "justification": "An international dataset based on surveys of more than 75,000 news consumers across 38 countries, including Germany. Covers news sources, digital platforms, trust in journalism, social media news consumption, and willingness to pay for online news. Particularly useful for examining the German news media environment toward the end of the 2010s."
    },
    {
      "title": "Eurobarometer – Media Use Trends (2010–2019)",
      "url_or_doi": "https://www.gesis.org/en/eurobarometer-data-service/overview/eb-trends-trend-files/list-of-trends/media-use",
      "justification": "A collection of harmonized European survey data documenting television viewing, radio listening, newspaper readership, and internet usage. Includes Germany-specific observations from surveys conducted throughout the 2010s. Useful for examining changes in media consumption, demographic differences, and comparisons between Germany and other European countries."
    },
    {
      "title": "ARD/ZDF Online Study 2010 – Internet and Media Usage in Germany",
      "url_or_doi": "https://www.ard-zdf-onlinestudie.de/files/2010/07-08-2010_van_Eimeren.pdf",
      "justification": "Research publication presenting survey findings from the 2010 ARD/ZDF Online Study. Contains quantitative information about internet penetration, online activities, and digital media consumption among German residents. Provides a valuable baseline for analyzing how German media consumption changed throughout the following decade. The linked resource presents published survey results rather than downloadable respondent-level microdata."
    },
    {
      "title": "ARD/ZDF Online Study 2015 – Internet Usage and Digital Media Trends",
      "url_or_doi": "https://www.ard-zdf-medienstudie.de/files/Download-Archiv/Onlinestudie/2015/0915_Frees_Koch.pdf",
      "justification": "Provides detailed statistical tables and survey findings on internet adoption, frequency of internet use, digital media engagement, and demographic differences in Germany in 2015. Includes historical comparisons with earlier years, making it useful for examining trends during the first half of the 2010s. The resource contains published statistical results rather than raw survey microdata."
    },
    {
      "title": "ARD/ZDF Online Study 2019 – Digital Media and Video-on-Demand Consumption",
      "url_or_doi": "https://www.ard-zdf-onlinestudie.de/files/2019/0919_Beisch_Koch_Schaefer.pdf",
      "justification": "Presents quantitative survey findings on internet penetration, online media usage, streaming services, and video-on-demand consumption in Germany in 2019. Includes historical comparisons with earlier years, allowing researchers to investigate the transition from traditional broadcasting to digital media during the 2010s. Particularly useful for understanding media consumption at the end of the decade."
    },
    {
      "title": "GESIS Eurobarometer Data Service – German and European Survey Data",
      "url_or_doi": "https://www.gesis.org/en/services/finding-and-accessing-data/browse",
      "justification": "GESIS provides access to archived social science survey datasets, including German and European research relevant to media consumption, political communication, public opinion, and digital engagement. Researchers can locate surveys conducted between 2010 and 2019 and identify variables concerning television, newspapers, online information, and media-related attitudes. This is a broader research data portal rather than a single media-specific dataset."
    },
    {
      "title": "ARD/ZDF Online Studies 2017–2018 – Digital Media Usage",
      "url_or_doi": "https://www.br.de/unternehmen/inhalt/organisation/medienforschung/br-onlinenutzung-texte-links-100.html",
      "justification": "An archive of ARD/ZDF online media research publications, including studies from 2017 and 2018. Covers internet usage, online video consumption, social media engagement, and the relationship between digital platforms and traditional broadcasting. Useful for examining changes in German media behavior during the later 2010s. Primarily provides published research and statistical findings."
    }
  ]
}
